def safe_quantile_edges(values: np.ndarray):
    q1, q2 = np.quantile(values, [1.0 / 3.0, 2.0 / 3.0])
    if q1 >= q2:
        vmin = float(np.min(values))
        vmax = float(np.max(values))
        if np.isclose(vmin, vmax):
            q1 = vmin + 1e-6
            q2 = vmax + 2e-6
        else:
